-- 93 Ghost Lantern: the ghosts are canvas groups drawn through a glow
-- material (the glow runs round each whole ghost, not round its parts), and
-- the cursed lantern's light subtracts - darkness that follows the mouse.
-- Space lifts the curse. The candles flicker on Noise. Generated by
-- tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/93-ghost-lantern.scene"
local CANDLES = 3
local GHOSTS = 3

local captions = true
local e = {}
local cursed = true
local strength = 1
local lx, ly = 0, -120
local t = 0

function init(entity)
    for _, n in ipairs({ "Lantern", "LanternGlow", "Darkness" }) do e[n] = Entity.find_by_name(n) end
    for i = 0, CANDLES - 1 do
        e["Candle" .. i] = Entity.find_by_name("Candle" .. i)
        e["Flame" .. i] = Entity.find_by_name("Flame" .. i)
    end
    for g = 0, GHOSTS - 1 do e["Ghost" .. g] = Entity.find_by_name("Ghost" .. g) end
end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    if Input.is_key_just_pressed("Space") then cursed = not cursed end
    t = t + dt

    -- The lantern drifts after the mouse.
    local mx, my = Input.get_mouse_world_position()
    local k = math.min(1, dt * 4)
    lx = lx + (mx - lx) * k
    ly = ly + (my - ly) * k
    Transform.set_position(e.Lantern, lx, ly)
    Transform.set_rotation(e.Lantern, math.sin(t * 2.1) * 0.08)
    strength = strength + ((cursed and 1 or 0) - strength) * math.min(1, dt * 3)
    Lighting.set_intensity(e.Darkness, 1.8 * strength)
    Sprite.set_color(e.LanternGlow, 0.32, 0.07, 1.0, 0.8 * strength)

    -- Candles flicker: two octaves of noise in time, a seed each.
    for i = 0, CANDLES - 1 do
        local f = Noise.fractal(t * 3.0, i * 10.0, { kind = "perlin", octaves = 2, seed = i })
        Lighting.set_intensity(e["Candle" .. i], 1.2 + f * 0.35)
        Sprite.set_color(e["Flame" .. i], 1.0, 0.57, 0.21, 0.75 + f * 0.25)
    end

    -- The ghosts float on slow loops; while the curse holds they lean
    -- toward the darkness.
    for g = 0, GHOSTS - 1 do
        local bx = -340 + g * 340 + math.sin(t * (0.31 + g * 0.07) + g * 2.0) * 120
        local by = 20 + math.sin(t * (0.53 + g * 0.05) + g) * 50
        local pull = 0.18 * strength
        Transform.set_position(e["Ghost" .. g], bx + (lx - bx) * pull, by + (ly - by) * pull)
        Transform.set_rotation(e["Ghost" .. g], math.sin(t * 0.9 + g) * 0.08)
    end
end
